// ---------------------------------------------------------------------------
// TEMPEL LABEL — kotak ini TIDAK menyebut satu pun nama sensor.
// Tugasnya: ambil semua angka dari pesan gateway, beri label, teruskan.
// Menambah sensor / menambah line TIDAK perlu menyunting kotak ini.
//
// SATU PESAN GATEWAY MASUK = SATU PAKET KELUAR, seketika.
//
// Versi pertama menahan nilai sampai denyut 1 detik berikutnya supaya semua
// gateway tergabung jadi satu paket. Pengukuran 17 jam di lapangan menunjukkan
// itu MEMBUANG 2,0% pembacaan: kalau dua pesan gateway jatuh di detik yang
// sama, yang kedua menimpa yang pertama sebelum sempat terkirim. Terukur 845
// pasang pesan berjarak <1 detik, dan defisitnya tersebar merata 1-2 per menit
// di 210 menit yang berbeda — bukan menggerombol seperti gangguan jaringan.
// Penggabungan antar-gateway itu juga semu: gateway tidak pernah serempak.
//
// SATU TOPIK PER GATEWAY: rnet/<site>/gw/<gateway>
// Bukan satu topik untuk seluruh plant. Alasannya bukan hemat byte — topiknya
// cuma dikirim sekali per paket — tapi supaya langganan bisa sebagian: R-Net
// (atau alat lain) boleh mendengarkan satu gateway saja tanpa ikut menerima
// semua yang lain, dan gateway yang bermasalah bisa diisolasi tanpa menyentuh
// yang sehat.
//
// NAMA KUNCI TANPA AWALAN GATEWAY
// Kunci ditulis 'waterlevel1', bukan 'lombok1.waterlevel1'. Nama gateway sudah
// ada DUA KALI di paket ini (di topik dan di kolom "gateway"), jadi mengulangnya
// di setiap kunci hanya menambah teks. Terukur di plant: awalan itu memakan ~8
// byte per nilai — 45,5 B jadi ~37,5 B per pembacaan, sekitar 18% isi paket.
// ---------------------------------------------------------------------------

// vvv SATU-SATUNYA baris yang diganti kalau flow ini dipakai di plant lain vvv
const SITE = 'lombok';
// ^^^--------------------------------------------------------------------^^^

// Nama gateway diambil dari POTONGAN TERAKHIR topik masuk:
//   fikri/vnet/lombok3  ->  "lombok3"  ->  terbit ke rnet/<site>/gw/lombok3
// Itu satu-satunya hubungan antara kotak mqtt in dan kotak ini, dan itulah
// sebabnya menambah gateway cukup menambah kotak mqtt in — tidak ada daftar
// gateway di dalam sini yang perlu ikut diperbarui.
const gw = String(msg.topic || '').split('/').pop();
if (!gw) { return null; }

// Payload biasanya sudah objek (mqtt in datatype auto-detect). Kalau brokernya
// mengirim teks mentah, coba urai sendiri sekali.
let p = msg.payload;
if (typeof p === 'string') {
    try { p = JSON.parse(p); } catch (e) { p = null; }
}
if (!p || typeof p !== 'object') {
    node.warn('Gateway ' + gw + ': isi pesan tidak dikenali, dilewati.');
    return null;
}

// Angka-angkanya ada di dalam .data. Kalau suatu saat gateway mengirim rata
// tanpa .data, pakai payload-nya langsung — jangan sampai diam-diam kosong.
const data = (p.data && typeof p.data === 'object') ? p.data : p;

// Field bawaan V-Box yang BUKAN sensor. 'id' adalah nomor seri gateway.
const BUKAN_SENSOR = ['id'];

const values = {};
let n = 0;
for (const k of Object.keys(data)) {
    if (BUKAN_SENSOR.indexOf(k) !== -1) { continue; }
    const v = data[k];

    // Number(), BUKAN parseFloat(). parseFloat membaca angka dari DEPAN teks
    // lalu berhenti: parseFloat('31c73eb96aaf...') = 31. Nomor seri gateway
    // Line 2 kebetulan diawali angka, jadi ia akan terkirim sebagai nilai
    // sensor palsu 31. Number() menolak seluruh teks itu (NaN). Ini ketahuan
    // dari data lapangan asli, bukan dari tebakan.
    const num = (typeof v === 'number')
        ? v
        : (typeof v === 'string' && v.trim() !== '' ? Number(v) : NaN);

    // Number.isFinite menolak NaN dan Infinity — nilai rusak tidak ikut
    // terkirim, tapi sensor lain di pesan yang sama tetap jalan.
    if (Number.isFinite(num)) {
        // Apa adanya dari gateway. Nama inilah yang diketik di R-Net >
        // Analisis > Sumber > Field, jadi mengubahnya di sini akan memutus
        // sensor yang sudah terdaftar.
        values[k] = num;
        n++;
    }
}

if (n === 0) {
    node.warn('Gateway ' + gw + ': tidak ada angka yang bisa dibaca dari pesan ini.');
    return null;
}

// Catat gateway yang pernah terlihat, supaya status kotak menunjukkan
// Line 3 langsung muncul sendiri begitu PC-nya online.
const gws = context.get('gws') || [];
if (gws.indexOf(gw) === -1) {
    gws.push(gw);
    gws.sort();
    context.set('gws', gws);
    node.warn('Gateway baru terdeteksi: ' + gw + ' (' + n + ' nilai). ' +
              'Daftarkan sensornya di R-Net > Kelola Sumber.');
}

// Hitung paket terkirim, sekadar supaya status kotak informatif.
const tot = (context.get('tot') || 0) + 1;
context.set('tot', tot);
node.status({
    fill: 'green', shape: 'dot',
    text: gw + ': ' + n + ' nilai | ' + gws.length + ' gateway (' +
          gws.join(', ') + ') | ' + tot + ' paket'
});

return {
    topic: 'rnet/' + SITE + '/gw/' + gw,
    payload: { site: SITE, gateway: gw, ts: new Date().toISOString(), values: values }
};
